from urllib.parse import quote
BASE=Path(__file__).resolve().parent
d=json.loads((BASE/'사업정의_데이터.json').read_text(encoding='utf-8'))
b=d['budget'];p1=b['1단계'];p2=b['2단계'];gross=p1['gross']+p2['gross'];diff=p1['headroom']+p2['headroom']
esc=html.escape
xlsx=next((BASE/'outputs').glob('*/*.xlsx')).relative_to(BASE).as_posix()
docs=[('01_서비스_정의서','서비스 정의서','단계별 납품 범위와 이용 흐름'),('02_요구사항_정의서','요구사항 정의서','목적·가정·변경·착수 조건'),('03_요구사항_명세서','요구사항 명세서','36개 요구와 처리·예외·검수'),('04_RFP_초안','RFP 초안','과업·납품·일정·제안 조건')]
cards=''.join(f'<article class="doc"><h3>{label}</h3><p>{desc}</p><a href="{quote(name+".docx")}">Word</a><a href="{quote(name+".md")}">Markdown</a></article>' for name,label,desc in docs)
reqcards=''.join(f'<details data-service="{r["service"]}" data-search="{esc(r["id"]+" "+r["title"]+" "+r["process"])}"><summary><span class="code">{r["id"]}</span><strong>{esc(r["title"])}</strong><span>{r["service"]}</span></summary><div class="body"><p>{esc(r["process"])}</p><p><b>검수</b> {esc(r["accept"])}</p><small>{r["phase"]} · {r["wp"]} · {r["test"]}</small></div></details>' for r in d['requirements'])
costrows=''.join(f'<tr><th>{p}</th><td>{b[p]["mm"]:.1f} MM</td><td>{b[p]["net"]:,}원</td><td>{b[p]["gross"]:,}원</td><td>{b[p]["headroom"]:,}원</td></tr>' for p in ['1단계','2단계'])
sources=''.join(f'<li><a href="{esc(s[2])}">{esc(s[1])}</a> <small>{esc(s[3])}</small></li>' for s in d['sources'][:2])
